package com.cinenest.rooms.internal;

import java.net.URI;
import java.nio.file.*;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.assertj.core.api.Assertions.*;
import static org.junit.jupiter.api.Assertions.assertTimeoutPreemptively;
import static com.cinenest.rooms.internal.AdvertisingMediaStore.*;

class AdvertisingMediaStorageContractTest {
    @Test void typedReferencesAndRedaction(){var id=new Identity(UUID.randomUUID(),UUID.randomUUID(),1);assertThatThrownBy(()->new Identity(id.objectId(),id.venueId(),0)).isInstanceOf(IllegalArgumentException.class);assertThatThrownBy(()->new Version("null")).isInstanceOf(IllegalArgumentException.class);var r=new Reference(id,new Version("private-version"),"a".repeat(64),10);assertThat(r.toString()).doesNotContain("private-version",id.objectId().toString());assertThat(new Failure(Outcome.INTEGRITY_FAILED)).hasMessage("Local media storage: INTEGRITY_FAILED");}
    @Test void endpointAndNamespaceFailClosed(){for(String uri:List.of("https://example.com","http://localhost:8333","http://127.0.0.1:8333/path","http://x:y@127.0.0.1:8333","http://127.0.0.1:8333?override=true"))assertThatThrownBy(()->new LocalAdvertisingMediaTestAdapter(URI.create(uri),"a".repeat(32),"a".repeat(16),"s".repeat(32),()->{})).isInstanceOf(Failure.class);assertThatThrownBy(()->new LocalAdvertisingMediaTestAdapter(URI.create("http://127.0.0.1:8333"),"../receipt","a".repeat(16),"s".repeat(32),()->{})).isInstanceOf(Failure.class);}
    @Test void oversizedObjectDeniedBeforeAnyTransport(){var checks=new java.util.concurrent.atomic.AtomicInteger();var a=new LocalAdvertisingMediaTestAdapter(URI.create("http://127.0.0.1:65534"),"a".repeat(32),"a".repeat(16),"s".repeat(32),checks::incrementAndGet);outcome(()->a.store(new Identity(UUID.randomUUID(),UUID.randomUUID(),1),UUID.randomUUID(),new byte[2*1024*1024+1]),Outcome.INVALID);assertThat(checks.get()).isZero();assertThat(a.creates()).isZero();assertThat(a.submitted()).isZero();}
    @Test void unmeasurableBudgetDoesNotReachTransport(){var a=new LocalAdvertisingMediaTestAdapter(URI.create("http://127.0.0.1:65534"),"a".repeat(32),"a".repeat(16),"s".repeat(32),()->{throw new Failure(Outcome.LIMIT_EXCEEDED);});assertThatThrownBy(a::initialize).isInstanceOfSatisfying(Failure.class,f->assertThat(f.outcome()).isEqualTo(Outcome.LIMIT_EXCEEDED));}
    @Test void noRuntimeAdapterOrAdditionalModule(){assertThat(LocalAdvertisingMediaTestAdapter.class.getProtectionDomain().getCodeSource().getLocation().getPath()).contains("test-classes");assertThat(AdvertisingMediaStore.class.getAnnotations()).isEmpty();assertThat(LocalAdvertisingMediaTestAdapter.class.getAnnotations()).isEmpty();assertThat(AdvertisingMediaStore.class.getDeclaredMethods()).allSatisfy(m->assertThat(m.toGenericString()).doesNotContain("payments","identity","booking","access","Seaweed","springframework"));}
    static String docker(String... args)throws Exception{var command=new ArrayList<>(List.of("docker"));command.addAll(List.of(args));var p=new ProcessBuilder(command).redirectError(ProcessBuilder.Redirect.DISCARD).start();if(!p.waitFor(20,TimeUnit.SECONDS)){p.destroyForcibly();throw new Failure(Outcome.UNAVAILABLE);}if(p.exitValue()!=0)throw new Failure(Outcome.UNAVAILABLE);return new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).trim();}
    static void measure(Path root){String stage="ROOT";try{if(Files.isSymbolicLink(root)||!Files.isDirectory(root))throw new Exception();long max=0;for(var args:List.of(List.of("du","-sb","--",root.toString()),List.of("du","-sk","--",root.toString()))){stage="COMMAND_START";var p=new ProcessBuilder(args).redirectError(ProcessBuilder.Redirect.DISCARD).start();stage="COMMAND_TIMEOUT";if(!p.waitFor(2,TimeUnit.SECONDS)){p.destroyForcibly();throw new Exception();}stage="COMMAND_EXIT";if(p.exitValue()!=0)throw new Exception();stage="PARSE";long n=Long.parseLong(new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.US_ASCII).trim().split("\\s+")[0]);if(args.get(1).equals("-sk"))n=Math.multiplyExact(n,1024);max=Math.max(max,n);}stage="SIZE";if(max+9L*1024*1024>128L*1024*1024)throw new Exception();}catch(Exception e){System.err.println("AD_MEDIA_A_BUDGET_"+stage);throw new Failure(Outcome.LIMIT_EXCEEDED);}}
    @Test void realFilesystemMeasurement()throws Exception{var dir=Files.createTempDirectory("ad-media-budget-");try{Files.write(dir.resolve("fixture"),new byte[16]);measure(dir);}finally{Files.deleteIfExists(dir.resolve("fixture"));Files.delete(dir);}}
    static void numericStatus(Object value){if(value instanceof Map<?,?> m){for(var e:m.entrySet()){if(Set.of("ReadOnly","Size","VolumeCount","Free","Max","ActiveVolumeCount","MaxVolumeCount","VolumeSizeLimitMB","WritableVolumeCount","DiskUsage").contains(e.getKey())&&(e.getValue() instanceof Number||e.getValue() instanceof Boolean))System.out.println("AD_MEDIA_A_NATIVE_"+e.getKey()+"="+e.getValue());numericStatus(e.getValue());}}else if(value instanceof List<?> list){for(Object item:list)numericStatus(item);}}
    static boolean hasDataNode(Object value){if(value instanceof Map<?,?> m){for(var entry:m.entrySet()){if(entry.getKey().equals("DataNodes")&&entry.getValue() instanceof List<?> nodes&&!nodes.isEmpty())return true;if(hasDataNode(entry.getValue()))return true;}}else if(value instanceof List<?> list){for(Object item:list)if(hasDataNode(item))return true;}return false;}
    static Reference storeWithReadOnlyRecovery(LocalAdvertisingMediaTestAdapter a,Identity id,UUID command,byte[] bytes,List<String> results)throws Exception{try{return a.store(id,command,bytes);}catch(Failure first){if(first.outcome()!=Outcome.UNAVAILABLE)throw first;int reserved=a.creates();var recovered=assertTimeoutPreemptively(Duration.ofSeconds(45),()->{while(true){try{return a.store(id,command,bytes);}catch(Failure pending){if(pending.outcome()!=Outcome.UNAVAILABLE&&pending.outcome()!=Outcome.STALE)throw pending;Thread.sleep(200);}}});assertThat(a.creates()).isEqualTo(reserved);assertThat(a.readExact(recovered)).containsExactly(bytes);results.add("restart-uncertain-write-read-only-reconciliation-no-second-put");return recovered;}}
    static void outcome(Runnable r,Outcome o){assertThatThrownBy(r::run).isInstanceOfSatisfying(Failure.class,f->assertThat(f.outcome()).isEqualTo(o));}
    @Test @EnabledIfEnvironmentVariable(named="CINENEST_AD_MEDIA_A",matches="true")
    void realIsolatedSeaweedContract()throws Exception{
        String run=System.getenv("AD_MEDIA_RUN_ID"),container="cn-ads-a-"+run;Path root=Path.of(System.getenv("AD_MEDIA_RUN_ROOT"));
        assertThat(root.getFileName().toString()).isEqualTo(container);assertThat(docker("inspect","--format","{{index .Config.Labels \"com.cinenest.run\"}}",container)).isEqualTo(run);
        var a=new LocalAdvertisingMediaTestAdapter(URI.create(System.getenv("AD_MEDIA_ENDPOINT")),run,System.getenv("AD_MEDIA_ACCESS"),System.getenv("AD_MEDIA_SECRET"),()->measure(root));
        var results=new ArrayList<String>();boolean cleaned=false;Throwable original=null;
        try{
            a.initialize();var fixture=Files.readAllBytes(Path.of("../frontend/public/cinema/violet-960.webp"));var different=Files.readAllBytes(Path.of("../frontend/public/cinema/blue-960.webp"));var id=new Identity(UUID.randomUUID(),UUID.randomUUID(),1);UUID cmd=UUID.randomUUID();var ref=a.store(id,cmd,fixture);assertThat(a.readExact(ref)).containsExactly(fixture);results.add("private-write-exact-version-digest");
            assertThat(a.store(id,cmd,fixture)).isEqualTo(ref);outcome(()->a.store(id,cmd,different),Outcome.CONFLICT);outcome(()->a.store(id,UUID.randomUUID(),fixture),Outcome.CONFLICT);results.add("immutable-intent-and-command-replay");
            var pool=Executors.newFixedThreadPool(4);try{var tasks=new ArrayList<Future<Reference>>();for(int i=0;i<4;i++)tasks.add(pool.submit(()->a.store(id,cmd,fixture)));for(var f:tasks)assertThat(f.get(15,TimeUnit.SECONDS)).isEqualTo(ref);assertThat(a.inventory()).hasSize(1);}finally{pool.shutdownNow();}results.add("concurrent-duplicate-one-version");
            outcome(()->a.readExact(new Reference(id,ref.version(),"0".repeat(64),fixture.length)),Outcome.INTEGRITY_FAILED);outcome(()->a.readExact(new Reference(new Identity(UUID.randomUUID(),id.venueId(),1),ref.version(),ref.sha256(),ref.bytes())),Outcome.NOT_FOUND);outcome(()->a.readExact(new Reference(id,new Version("missing-version"),ref.sha256(),ref.bytes())),Outcome.STALE);results.add("integrity-missing-and-wrong-version-denied");
            var anonymous=a.request("GET",a.path(id),"versionId="+LocalAdvertisingMediaTestAdapter.enc(ref.version().value()),new byte[0],false,0,false);assertThat(anonymous.status()).isEqualTo(403);var other=a.request("GET","/not-owned-"+run,"",new byte[0],false,0,true);assertThat(other.status()).isIn(403,404);results.add("anonymous-denied-no-public-delivery");
            assertThat(a.prefix).isEqualTo("runs/"+run+"/");assertThat(a.inventory()).allSatisfy(e->assertThat(e.key()).startsWith(a.prefix).doesNotContain("receipt"));results.add("dedicated-namespace-no-payments-path");
            a.discardNextPutReply=true;var lostId=new Identity(UUID.randomUUID(),id.venueId(),1);UUID lostCmd=UUID.randomUUID();outcome(()->a.store(lostId,lostCmd,fixture),Outcome.UNAVAILABLE);int before=a.creates();var recovered=a.store(lostId,lostCmd,fixture);assertThat(a.creates()).isEqualTo(before);assertThat(a.readExact(recovered)).containsExactly(fixture);results.add("injected-lost-reply-exact-reconciliation-no-second-put");
            var changed=a.request("PUT",a.path(id),"",different,false,1,true);assertThat(changed.status()).isEqualTo(200);assertThat(a.exactBytes(ref)).containsExactly(fixture);outcome(()->a.readExact(ref),Outcome.STALE);results.add("native-historical-version-read-proven-unexpected-new-version-stale");
            docker("stop","--time","15",container);outcome(()->a.readExact(recovered),Outcome.UNAVAILABLE);docker("start",container);String restartedPort=docker("port",container,"8333/tcp");assertThat(restartedPort).matches("127\\.0\\.0\\.1:[0-9]+");String restartedEndpoint="http://"+restartedPort;if(!restartedEndpoint.equals(System.getenv("AD_MEDIA_ENDPOINT")))System.out.println("AD_MEDIA_A_RESTART_PORT_CHANGED");a.reconnectLocal(URI.create(restartedEndpoint));assertTimeoutPreemptively(Duration.ofSeconds(45),()->{while(true){try{var cluster=com.nimbusds.jose.util.JSONObjectUtils.parse(docker("exec",container,"wget","-q","-O","-","http://127.0.0.1:9333/cluster/status"));var topology=com.nimbusds.jose.util.JSONObjectUtils.parse(docker("exec",container,"wget","-q","-O","-","http://127.0.0.1:9333/dir/status"));if(!Boolean.TRUE.equals(cluster.get("IsLeader"))||!hasDataNode(topology)){Thread.sleep(200);continue;}assertThat(a.readExact(recovered)).containsExactly(fixture);break;}catch(Failure f){if(f.outcome()!=Outcome.UNAVAILABLE)throw f;Thread.sleep(100);}}});results.add("outage-fail-closed-and-container-restart-persistence");
            numericStatus(com.nimbusds.jose.util.JSONObjectUtils.parse(docker("exec",container,"wget","-q","-O","-","http://127.0.0.1:9333/dir/status")));
            var markerId=new Identity(UUID.randomUUID(),id.venueId(),1);var markerRef=storeWithReadOnlyRecovery(a,markerId,UUID.randomUUID(),fixture,results);var marker=a.request("DELETE",a.path(markerId),"",new byte[0],false,1,true);assertThat(marker.status()).isIn(200,204);outcome(()->a.readExact(markerRef),Outcome.STALE);assertThat(a.inventory()).anyMatch(LocalAdvertisingMediaTestAdapter.Entry::marker);results.add("delete-marker-counted-and-denied");
            a.removeExact(recovered);outcome(()->a.readExact(recovered),Outcome.NOT_FOUND);results.add("exact-owned-version-removal");
            assertThat(a.creates()).isLessThanOrEqualTo(10);assertThat(a.submitted()).isLessThanOrEqualTo(20L*1024*1024);measure(root);
        }catch(Exception|AssertionError e){original=e;throw e;}finally{Files.writeString(root.resolve("cleanup.started.tmp"),Long.toString(System.currentTimeMillis()));Files.move(root.resolve("cleanup.started.tmp"),root.resolve("cleanup.started"),StandardCopyOption.ATOMIC_MOVE);try{a.cleanup();cleaned=true;}catch(Failure f){if(original!=null)original.addSuppressed(f);else throw f;}}
        assertThat(cleaned).isTrue();results.add("owned-versions-markers-bucket-cleanup-verified");
        String json=com.nimbusds.jose.util.JSONObjectUtils.toJSONString(Map.of("status","PASS","results",results,"potentialVersionCreations",a.creates(),"submittedBytes",a.submitted(),"objectsAndBucketAbsent",cleaned,"storageBudgetKind","MONITORED_NOT_FILESYSTEM_QUOTA"));Files.writeString(root.resolve("contract-results.json"),json);System.out.println("AD_MEDIA_A_PASS "+results.size()+" scenarios;no public delivery;owned object cleanup verified");
    }
}
